  pharmacist:['D01','D03','D07','D08','D09','D23','D28'],billing:['D01','D03','D22','D23','D24','D26','D35'],
  finance:['D23','D24','D25','D26'],inventory:['D27','D28','D29','D31'],quality:['D29','D30','D31','D32','D33','D36'],
