function domain(id:string,name:string,purpose:string,steps:string[],completion:string,limits:string):GuideDomain {
  return {id,name,purpose,roles:Object.keys(ROLE_DOMAINS).filter(role=>ROLE_DOMAINS[role].includes(id)),steps,completion,limits}
}

